import{_ as t,a as s,b as o}from"./chunks/ugso_jinja_composed_value.CvcSZlNs.js";import{_ as a,o as n,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const c="/assets/blocks-for-ha/blocks/fr/ugso_and.png",d="/assets/blocks-for-ha/blocks/fr/ugso_or.png",l="/assets/blocks-for-ha/jinja/fr.png",_=JSON.parse('{"title":"Automatisations HA avancées et Jinja","description":"Déclencheurs, conditions, cibles, groupes d’actions et reconnaissance Jinja expérimentale.","frontmatter":{"title":"Automatisations HA avancées et Jinja","description":"Déclencheurs, conditions, cibles, groupes d’actions et reconnaissance Jinja expérimentale."},"headers":[],"relativePath":"fr/projects/blocks-for-ha/advanced.md","filePath":"fr/projects/blocks-for-ha/advanced.md","lastUpdated":1793198184000}'),u={name:"fr/projects/blocks-for-ha/advanced.md"};function p(m,e,h,g,b,f){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="automatisations-ha-avancees-et-jinja" tabindex="-1">Automatisations HA avancées et Jinja <a class="header-anchor" href="#automatisations-ha-avancees-et-jinja" aria-label="Permalink to &quot;Automatisations HA avancées et Jinja&quot;">​</a></h1><h2 id="options-ha-par-engrenage-depuis-0-1-61" tabindex="-1">Options HA par engrenage depuis 0.1.61 <a class="header-anchor" href="#options-ha-par-engrenage-depuis-0-1-61" aria-label="Permalink to &quot;Options HA par engrenage depuis 0.1.61&quot;">​</a></h2><p>Glisser une option de gauche dans la liste du dialogue. Chaque option ajoute sa propre ligne sous les champs obligatoires. Ordre et lignes vides sélectionnées sont enregistrés dans le projet. Retirer une option réinitialise sa valeur. Les options importées, y compris <code>false</code>, <code>0</code>, listes et modèles, apparaissent automatiquement et restent inchangées au chargement. Tous les libellés sont disponibles en DE/EN/FR.</p><p><img src="'+t+'" alt="Étape HA compacte"></p><table tabindex="0"><thead><tr><th>Blocs HA examinés</th><th>Champs obligatoires / options par engrenage</th></tr></thead><tbody><tr><td>Tous les déclencheurs avancés et déclencheur général</td><td>Type et champs essentiels restent. Limites, filtres d’état, durée, attributs, modèles, filtres d’événement, appareil, ID, nom, activation et variables selon le déclencheur.</td></tr><tr><td>Condition HA avancée</td><td>Type et champs essentiels ; limites horaires, jours, attributs, durée, nom et activation facultatifs.</td></tr><tr><td>Étape HA avancée</td><td>Action et entité ; appareil, zone, étage, label, données, variable de réponse, nom, activation, gestion d’erreur et métadonnées ajoutables séparément.</td></tr><tr><td>Action avec cible, action générale, émission d’événement</td><td>Nom et cible nécessaires conservés ; données, variable de réponse, listes, métadonnées ou options d’étape.</td></tr><tr><td>Attente de déclencheurs, motif horaire</td><td>Chaîne conservée ; délai maximal, comportement à expiration et options d’étape. Champs horaires sélectionnables séparément ; au moins un est nécessaire pour un YAML valide.</td></tr><tr><td>Calendrier, température, intégration</td><td>Champs essentiels et seuils obligatoires conservés ; autres cibles, options et ID.</td></tr><tr><td>Déclencheurs simples</td><td>ID, plusieurs entités/états/heures, tout changement, durée, décalage solaire et filtre d’événement selon le bloc.</td></tr><tr><td>Actions/valeurs simples, variables</td><td>Aucun engrenage inutile pour les seuls champs essentiels. Noms et valeurs des variables restent modifiables directement.</td></tr><tr><td>Si, choix, parallèle, objets, listes et fonctions</td><td>Éditeurs spécialisés existants conservés.</td></tr></tbody></table><p><strong>et</strong>, <strong>ou</strong> et <strong>non</strong> sont des blocs séparés. et/ou possèdent un éditeur extensible sans sélection d’opérateur ; non a une entrée. Les groupes combinés existants restent lisibles, y compris avec plusieurs entrées de négation. L’import YAML utilise les variantes séparées lorsqu’elles sont exactement équivalentes.</p><p><img src="'+c+'" alt="et"></p><p><img src="'+d+'" alt="ou"></p><p>Vérification : rendu de toutes les définitions DE/EN/FR, compatibilité projet/YAML et ajout/retrait des options. Entités, intégrations et données d’exécution restent à vérifier dans HA.</p><p>Depuis <strong>0.1.43</strong>, les blocs HA avancés proposent des champs nommés au lieu d’un grand objet JSON. Toujours 163 types ; <strong>HA avancé</strong> et <strong>Jinja (expérimental)</strong> complètent les blocs simples. L’import vérifie la structure ; vérifier ensuite intégrations, IDs d’appareils, modèles et exécution dans Home Assistant.</p><p>Les 15 déclencheurs classiques avancés, conditions et étapes générales, cibles/options d’intégration, calendriers, seuils de température, motifs horaires, variables et options d’attente/étape utilisent des champs structurés. <strong>numeric_state</strong> propose entité, seuil supérieur, seuil inférieur, attribut, modèle, durée et ID. Les champs facultatifs vides sont omis ; les deux seuils sont indépendants. Les entités acceptent recherche HA, IDs manuels, listes JSON et modèles. Après changement du type d’un bloc général, ajouter si nécessaire les autres champs dans ses options.</p><p>Saisir listes et objets en JSON ; <code>null</code> est une valeur nulle explicite, <code>&quot;null&quot;</code> du texte. États et payloads restent du texte. Les valeurs inchangées conservent leurs types et le texte Jinja exact. <strong>Options supplémentaires (JSON)</strong> conserve les propriétés complémentaires. Données complexes et branches imbriquées restent des champs JSON séparés ; elles ne sont pas automatiquement décomposées en branches connectées. Les anciens projets JSON chargent automatiquement les nouveaux champs ; import/export YAML et projets restent compatibles.</p><p><img src="'+s+'" alt="Déclencheur numeric-state avec champs séparés"></p><p>Spécification originale : <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">Déclencheurs HA</a>, <a href="https://www.home-assistant.io/docs/scripts/conditions/" target="_blank" rel="noreferrer">Conditions HA</a>, <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">Étapes HA</a>.</p><h2 id="declencheurs-et-conditions" tabindex="-1">Déclencheurs et conditions <a class="header-anchor" href="#declencheurs-et-conditions" aria-label="Permalink to &quot;Déclencheurs et conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Domaine</th><th>Ajouts pris en charge</th></tr></thead><tbody><tr><td>État</td><td>Plusieurs entités ; <code>from</code>, <code>to</code>, <code>not_from</code>, <code>not_to</code>, listes et <code>null</code> ; attributs et <code>for</code>.</td></tr><tr><td>Nombres</td><td>Deux bornes, entités auxiliaires comme bornes, attributs, <code>value_template</code>, durée et plusieurs entités.</td></tr><tr><td>Heure</td><td>Heures et listes, auxiliaires/capteurs horaires, source avec décalage, jours et motifs horaires.</td></tr><tr><td>Soleil et HA</td><td>Lever/coucher avec décalage ; démarrage et arrêt de HA.</td></tr><tr><td>Autres déclencheurs</td><td>MQTT, modèle, webhook, zone, appareil, tag, conversation, géolocalisation, événement et calendrier classique.</td></tr><tr><td>Intégrations</td><td><code>calendar.event_started/ended</code>, <code>temperature.changed</code>, <code>power.changed</code>, <code>motion.detected</code>, <code>timer.finished</code>. Cibles appareil, zone, étage et étiquette également possibles.</td></tr><tr><td>Conditions</td><td>Heure/jour, état avec listes/attribut/durée/<code>match</code>, bornes numériques, soleil, zone, appareil, ID du déclencheur, modèle et ET/OU/NON imbriqués. La forme abrégée d’un modèle est conservée.</td></tr></tbody></table><p>Le bloc d’intégration propose un menu puissance, mouvement et minuteur. Saisir cible et options séparément. Changer d’intégration remplace uniquement les exemples inchangés ; les valeurs personnalisées restent. Les déclencheurs JSON avancés acceptent <code>alias</code>, <code>enabled</code>, <code>id</code> et les variables du déclencheur. Types inconnus et champs non pris en charge sont refusés avec un message.</p><h2 id="cibles-variables-et-options" tabindex="-1">Cibles, variables et options <a class="header-anchor" href="#cibles-variables-et-options" aria-label="Permalink to &quot;Cibles, variables et options&quot;">​</a></h2><p><strong>Action HA avec type de cible</strong> propose <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> et <code>label_id</code>. Saisir un ID, une liste JSON ou un modèle HA. <strong>Étape HA avancée</strong> accepte plusieurs types de cibles simultanément. Les données d’action peuvent être un objet ou un modèle HA complet ; l’import conserve les deux formes.</p><p>Les variables acceptent listes et objets imbriqués. Chaque variable existante dispose d’un champ ; ajouter de nouveaux noms dans les options supplémentaires. Les options <code>alias</code>, <code>enabled</code>, <code>continue_on_error</code>, variables de réponse et métadonnées disposent de champs séparés. <code>enabled</code> accepte un booléen ou modèle HA ; <code>continue_on_error</code> un booléen.</p><p>Sous <strong>Projet et description → Options HA</strong>, modifier <code>variables</code>, <code>trigger_variables</code>, <code>initial_state</code>, <code>trace.stored_traces</code> et <code>max_exceeded</code>. <strong>Appliquer</strong> accepte uniquement des options valides. Les options omises sont supprimées ; <code>{}</code> supprime toutes les options gérées par ce champ. Nom et mode restent séparés. Sans <code>alias</code>, le nom de fichier devient <code>automation.yaml</code>. Depuis 0.1.46, toutes les commandes suivent la langue choisie.</p><h2 id="attente-et-groupes-d-actions" tabindex="-1">Attente et groupes d’actions <a class="header-anchor" href="#attente-et-groupes-d-actions" aria-label="Permalink to &quot;Attente et groupes d’actions&quot;">​</a></h2><ul><li><strong>Attendre un déclencheur</strong> relie une chaîne de déclencheurs ; <code>timeout</code> / <code>continue_on_timeout</code> se règlent dans les options.</li><li><strong>Groupe d’actions</strong> produit une <code>sequence</code> native avec étapes connectables.</li><li><strong>Parallèle</strong> lance des branches natives. <strong>L’engrenage</strong> permet 1–100 branches. Supprimer une branche occupée laisse ses blocs déconnectés ; les reconnecter ou supprimer.</li><li><strong>Continuer seulement si</strong> produit une condition comme étape d’action. Événement, réponse Assist et scène ont leurs blocs.</li><li>Les répétitions acceptent aussi des listes/objets littéraux pour <code>for_each</code> ; les délais acceptent unités combinées et fractions. Les formes complexes ou mixtes restent des étapes JSON.</li></ul><p>Ces blocs exportent les séquences natives HA. L’exécution se fait dans HA, sans moteur de script local.</p><h2 id="jinja-experimental" tabindex="-1">Jinja (expérimental) <a class="header-anchor" href="#jinja-experimental" aria-label="Permalink to &quot;Jinja (expérimental)&quot;">​</a></h2><p>Depuis <strong>0.1.41</strong>, <strong>Jinja einlesen</strong> peut décomposer les modèles en blocs imbriqués modifiables. Coller le modèle, vérifier l’aperçu, laisser <strong>Décomposer en blocs modifiables</strong> activé et choisir éventuellement <strong>Als Bedingung</strong>. <strong>Block erstellen</strong> place la structure connectée à côté de l’automatisation. Relier le bloc valeur extérieur à une affectation de variable ou une entrée de valeur ; relier le bloc condition à une entrée booléenne. Désactiver la décomposition crée un bloc de texte original.</p><p><img src="'+o+'" alt="Bloc valeur Jinja composé"></p><p>Exemple : <code>Eau: {{ states(&#39;sensor.water&#39;) | float(0) | round(1) }} °C</code> devient des parties de texte et une sortie contenant une fonction d’entité, <code>float</code> et <code>round</code>. Le champ d’entité ouvre la recherche existante. Modifier séparément entité, filtres, arguments et précision. L’import YAML décompose les valeurs correspondantes, par exemple dans une affectation unique de variable, et les conditions de modèle. Les formes existantes plus spécifiques sont conservées. Les modèles dans le JSON de données/options restent dans le champ JSON.</p><p><img src="'+l+'" alt="Structure modifiable de l’exemple"></p><table tabindex="0"><thead><tr><th>Parties prises en charge</th><th>Représentation</th></tr></thead><tbody><tr><td><code>states</code>, <code>state_attr</code>, <code>is_state</code>, <code>is_state_attr</code> avec ID d’entité fixe</td><td>Fonction d’entité avec recherche et entrées d’arguments</td></tr><tr><td><code>now()</code>, noms simples de variables, nombres, chaînes entre guillemets, booléens et <code>none</code></td><td>Blocs d’expression ; noms de variables Jinja dans des champs texte</td></tr><tr><td><code>float</code>, <code>int</code>, <code>round</code>, <code>default</code>, <code>abs</code>, <code>lower</code>, <code>upper</code>, <code>trim</code>, <code>length</code>, <code>string</code>, <code>list</code>, <code>join</code>, <code>replace</code></td><td>Filtres imbriqués avec 0–3 arguments positionnels</td></tr><tr><td><code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>//</code>, <code>%</code>, <code>~</code>, comparaisons, <code>and</code>, <code>or</code>, <code>not</code></td><td>Calculs/comparaisons avec parenthèses explicites</td></tr><tr><td><code>valeur if condition else autre_valeur</code></td><td>Sélection conditionnelle de valeur</td></tr><tr><td>Texte, <code>{{ ... }}</code>, simples <code>{% if ... %}...{% else %}...{% endif %}</code></td><td>Blocs texte, sortie, liaison et si/sinon</td></tr><tr><td><code>{% for item in items %}...{% else %}...{% endfor %}</code></td><td>Boucle simple sur une expression, cas vide facultatif et parties imbriquées</td></tr></tbody></table><p><strong>Conserver l’original :</strong> Les structures inchangées gardent le texte exact, espaces compris, après rechargement et annulation/rétablissement. Les modifications génèrent du Jinja reformatté ; restaurer les champs à la même structure rétablit l’original. Les projets Blockly sauvegardent structure et original. YAML sauvegarde le texte, analysé à nouveau lors de l’import.</p><div class="warning custom-block"><p class="custom-block-title">Limites de décomposition</p><p>Analyseur original d’un sous-ensemble limité de Jinja. Dès qu’une partie n’est pas prise en charge, le <strong>modèle entier</strong> reste un bloc original modifiable. Exemples : <code>set</code>, <code>namespace</code>, accès aux objets/listes, littéraux liste/objet, tests <code>is defined</code>, comparaisons en chaîne, <code>elif</code>, arguments nommés, fonctions/filtres inconnus, commentaires et marqueurs de contrôle des espaces. Pas de décomposition partielle, de garantie syntaxique ni d’exécution locale. Le bloc valeur extérieur accepte des modèles entiers ; seul un affichage Jinja unique s’intègre dans un autre calcul. Entrées manquantes ou littéraux invalides empêchent l’export. Limites : 10000 caractères, 100 parties et imbrication bornée. Les noms de variables Jinja ne sont pas renommés automatiquement avec les autres variables Blockly. Home Assistant évalue le modèle ; y tester.</p></div><p>Les projets Blockly conservent aussi formes et positions. YAML → Blockly → export conserve les valeurs prises en charge, y compris les champs facultatifs absents. Limites : 100 entrées/branches, 10 niveaux d’imbrication et tailles de données/modèles limitées. Les options spécifiques aux appareils ne sont pas exhaustives ; un champ refusé n’est jamais supprimé silencieusement.</p><h2 id="sources-originales-et-licences" tabindex="-1">Sources originales et licences <a class="header-anchor" href="#sources-originales-et-licences" aria-label="Permalink to &quot;Sources originales et licences&quot;">​</a></h2><p>Implémentation originale UGSo selon les spécifications publiques, sans copier le moteur ioBroker. Licences Blockly/plugins sous <strong>Über &amp; Lizenzen</strong> ; application Apache-2.0.</p><ul><li><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">Déclencheurs HA</a>, <a href="https://www.home-assistant.io/docs/scripts/conditions/" target="_blank" rel="noreferrer">conditions</a>, <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">séquences</a> et <a href="https://www.home-assistant.io/docs/automation/yaml/" target="_blank" rel="noreferrer">YAML</a>.</li><li><a href="https://www.home-assistant.io/triggers/power.changed/" target="_blank" rel="noreferrer">Puissance</a>, <a href="https://www.home-assistant.io/triggers/motion.detected/" target="_blank" rel="noreferrer">mouvement</a>, <a href="https://www.home-assistant.io/triggers/timer.finished/" target="_blank" rel="noreferrer">minuteur terminé</a>.</li><li><a href="https://jinja.palletsprojects.com/en/stable/templates/" target="_blank" rel="noreferrer">Modèles Jinja</a> et <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">modèles HA</a>.</li><li><a href="https://docs.blockly.com/guides/create-custom-blocks/overview/" target="_blank" rel="noreferrer">Blocs personnalisés Blockly</a> et <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/blocks_for_ha" target="_blank" rel="noreferrer">code UGSo</a>.</li></ul>',36)])])}const A=a(u,[["render",p]]);export{_ as __pageData,A as default};
